<template><div class="biz-page"><PageHeader eyebrow="采购管理 · 逆向业务" title="采购退货管理" description="审核采购退货，完成库存扣减与供应商应付款冲销"><el-button type="primary" :icon="Plus" @click="openCreate">新建采购退货</el-button></PageHeader><section class="biz-card"><div class="biz-toolbar"><el-input v-model="query.keyword" placeholder="退货单、采购单或供应商" clearable/><el-select v-model="query.status" placeholder="全部状态" clearable><el-option v-for="s in statuses" :key="s" :label="s" :value="s"/></el-select><el-button type="primary" @click="search">查询</el-button><el-button @click="reset">重置</el-button><span class="biz-toolbar__summary">共 {{total}} 条</span></div><el-table v-loading="loading" :data="rows" border><el-table-column prop="returnNo" label="退货单号" min-width="180"/><el-table-column prop="purchaseCode" label="原采购单" min-width="160"/><el-table-column prop="supplierName" label="供应商" min-width="150"/><el-table-column label="退货日期" width="120"><template #default="{row}">{{formatDate(row.returnDate)}}</template></el-table-column><el-table-column label="退货金额" width="125" align="right"><template #default="{row}">{{formatMoney(row.totalAmount)}}</template></el-table-column><el-table-column prop="status" label="状态" width="100"/><el-table-column label="操作" width="230" fixed="right"><template #default="{row}"><el-button link type="primary" @click="openDetail(row)">详情</el-button><el-button v-if="row.status==='待审核'" link type="success" @click="approve(row)">审核通过</el-button><el-button v-if="row.status==='已审核'" link type="primary" @click="complete(row)">完成出库</el-button><el-button v-if="row.status!=='已完成'&&row.status!=='已作废'" link type="danger" @click="cancel(row)">作废</el-button></template></el-table-column></el-table><div class="biz-pagination"><el-pagination v-model:current-page="query.page" v-model:page-size="query.size" :total="total" layout="total, prev, pager, next" @change="load"/></div></section>
<el-dialog v-model="createVisible" title="新建采购退货" width="760px"><el-form label-position="top"><el-form-item label="原采购单（已入库）"><div class="source"><el-select v-model="form.purchaseId" filterable placeholder="选择已入库采购单" style="flex:1" @change="readPurchase"><el-option v-for="p in stockedPurchases" :key="p.orderId" :label="`${p.orderCode} · ${p.supplierName || '供应商#' + p.supplierId}`" :value="p.orderId"/></el-select><el-button :loading="sourceLoading" :disabled="!form.purchaseId" @click="readPurchase">读取采购单</el-button></div></el-form-item><el-form-item label="退货日期"><el-date-picker v-model="form.returnDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="退货原因"><el-input v-model="form.remark" maxlength="200"/></el-form-item><el-table v-if="source?.details?.length" :data="source.details" border><el-table-column prop="productName" label="商品" min-width="180"><template #default="{row}">{{row.productName||`商品 #${row.productId}`}}</template></el-table-column><el-table-column prop="purchaseQuantity" label="采购数量" width="110"/><el-table-column label="本次退货数量" width="180"><template #default="{row}"><el-input-number v-model="quantities[row.productId]" :min="0" :max="row.purchaseQuantity"/></template></el-table-column></el-table></el-form><template #footer><el-button @click="createVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="create">提交退货申请</el-button></template></el-dialog>
<el-drawer v-model="detailVisible" title="采购退货详情" size="620px"><div v-loading="detailLoading" v-if="selected"><h2>{{selected.returnNo}}</h2><el-descriptions :column="2" border><el-descriptions-item label="原采购单">{{selected.purchaseCode}}</el-descriptions-item><el-descriptions-item label="供应商">{{selected.supplierName}}</el-descriptions-item><el-descriptions-item label="经办人">{{selected.operatorName}}</el-descriptions-item><el-descriptions-item label="状态">{{selected.status}}</el-descriptions-item><el-descriptions-item label="金额">{{formatMoney(selected.totalAmount)}}</el-descriptions-item><el-descriptions-item label="备注">{{selected.remark||'-'}}</el-descriptions-item></el-descriptions><h3>退货商品</h3><el-table :data="selected.details||[]" border><el-table-column prop="productName" label="商品"/><el-table-column prop="quantity" label="数量" width="90"/><el-table-column label="退货单价" width="120"><template #default="{row}">{{formatMoney(row.returnPrice)}}</template></el-table-column><el-table-column label="小计" width="120"><template #default="{row}">{{formatMoney(row.subtotal)}}</template></el-table-column></el-table><h3>状态时间线</h3><el-timeline><el-timeline-item v-for="log in timeline" :key="log.logId" :timestamp="formatDateTime(log.changeTime)"><b>{{log.newStatus}}</b><p>{{log.remark||'-'}}</p></el-timeline-item></el-timeline></div></el-drawer></div></template>
<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{Plus}from'@element-plus/icons-vue';import{ElMessage,ElMessageBox}from'element-plus';import PageHeader from'../../components/PageHeader.vue';import{purchaseReturnApi}from'../../api/purchaseReturn';import{purchaseApi}from'../../api/purchase';import{inventoryApi}from'../../api/inventory';import{useAuthStore}from'../../stores/auth';import type{PurchaseOrder}from'../../types/purchase';import type{OrderStatusLog,PurchaseReturn,PurchaseReturnQuery}from'../../types/purchaseReturn';import{formatDate,formatDateTime,formatMoney}from'../../utils/format';const auth=useAuthStore(),statuses=['待审核','已审核','已完成','已作废'];const query=reactive<PurchaseReturnQuery>({page:1,size:10,keyword:'',status:''}),rows=ref<PurchaseReturn[]>([]),total=ref(0),loading=ref(false);const createVisible=ref(false),saving=ref(false),sourceLoading=ref(false),source=ref<PurchaseOrder|null>(null),quantities=reactive<Record<number,number>>({}),form=reactive({purchaseId:null as number|null,returnDate:new Date().toLocaleDateString('en-CA'),remark:''});const stockedPurchases=ref<PurchaseOrder[]>([]);const detailVisible=ref(false),detailLoading=ref(false),selected=ref<PurchaseReturn|null>(null),timeline=ref<OrderStatusLog[]>([]);const userId=()=>Number(auth.userInfo?.userId||0);const unwrapPurchase=(raw:unknown):PurchaseOrder|null=>{const value=raw as any;return value?.data?.data??value??null};async function load(){loading.value=true;try{const r=await purchaseReturnApi.getList({...query,keyword:query.keyword||undefined,status:query.status||undefined});rows.value=r?.list||[];total.value=r?.total||0}finally{loading.value=false}}function search(){query.page=1;load()}function reset(){Object.assign(query,{page:1,size:10,keyword:'',status:''});load()}async function loadStockedPurchases(){try{const r:any=await purchaseApi.getList({page:1,size:200,status:'已入库'});stockedPurchases.value=r?.list??r?.data?.list??r?.data?.data?.list??[]}catch{stockedPurchases.value=[]}}function openCreate(){source.value=null;Object.keys(quantities).forEach(k=>delete quantities[Number(k)]);form.purchaseId=null;createVisible.value=true;loadStockedPurchases()}async function readPurchase(){if(!form.purchaseId)return;sourceLoading.value=true;try{const p=unwrapPurchase(await purchaseApi.getDetail(form.purchaseId));if(!p||p.status!=='已入库'){ElMessage.warning('只能退回已入库采购单');source.value=null;return}source.value=p;(p.details||[]).forEach(x=>quantities[x.productId]=0)}finally{sourceLoading.value=false}}async function create(){if(!source.value||!form.purchaseId||userId()<=0)return ElMessage.warning('请读取采购单并确认登录用户');const details=(source.value.details||[]).filter(x=>(quantities[x.productId]||0)>0).map(x=>({productId:x.productId,quantity:quantities[x.productId]}));if(!details.length)return ElMessage.warning('请填写退货数量');saving.value=true;try{await purchaseReturnApi.create({purchaseId:form.purchaseId,operatorId:userId(),returnDate:form.returnDate,remark:form.remark||null,details});ElMessage.success('采购退货申请已创建');createVisible.value=false;await load()}finally{saving.value=false}}async function openDetail(row:PurchaseReturn){detailVisible.value=true;detailLoading.value=true;try{[selected.value,timeline.value]=await Promise.all([purchaseReturnApi.getDetail(row.returnId),purchaseReturnApi.getTimeline(row.returnId)])}finally{detailLoading.value=false}}async function approve(row:PurchaseReturn){await ElMessageBox.confirm('确认审核通过该采购退货单吗？','审核采购退货',{type:'warning'});await purchaseReturnApi.approve(row.returnId,userId(),'审核通过');ElMessage.success('审核通过');await load()}async function complete(row:PurchaseReturn){const warehouses=await inventoryApi.getWarehouses();const first=warehouses?.find(x=>x.status!=='禁用');if(!first)return ElMessage.warning('没有可用仓库');await ElMessageBox.confirm(`确认从“${first.warehouseName}”完成退货出库并冲减应付款吗？`,'完成采购退货',{type:'warning'});await purchaseReturnApi.complete(row.returnId,userId(),first.warehouseId,'采购退货出库');ElMessage.success('采购退货已完成');await load()}async function cancel(row:PurchaseReturn){await ElMessageBox.confirm('确认作废该采购退货单吗？','作废退货单',{type:'warning'});await purchaseReturnApi.remove(row.returnId);ElMessage.success('已作废');await load()}onMounted(load)</script><style scoped>.source{display:flex;gap:10px}.biz-pagination{margin-top:14px;display:flex;justify-content:flex-end}h3{margin-top:22px}</style>
